import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.PU0FRLnN.js";var i=JSON.parse(`{"title":"What is GraphScribe?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-graphscribe.md","filePath":"guide/what-is-graphscribe.md"}`),a={name:`guide/what-is-graphscribe.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-graphscribe" tabindex="-1">What is GraphScribe? <a class="header-anchor" href="#what-is-graphscribe" aria-label="Permalink to “What is GraphScribe?”">​</a></h1><p>GraphScribe is an <strong>editor plugin for Unreal Engine 5.7/5.8</strong> that turns your Blueprint logic into <strong>text and diagrams</strong> you can actually read and that AI tools can actually understand.</p><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to “The problem”">​</a></h2><p>Unreal stores Blueprints and DataAssets as <code>.uasset</code> files. Those files are:</p><ul><li><strong>Binary:</strong> you can&#39;t read them in a text editor.</li><li><strong>Hidden from AI:</strong> coding agents and knowledge tools can&#39;t search inside them.</li><li><strong>Invisible in :</strong> pull requests show &quot;changed a binary file&quot;, not <em>what</em> changed.</li></ul><p>So gameplay logic that lives in Blueprint graphs is effectively locked inside the editor. To inspect a call graph, class references, or default values, you have to open every Blueprint by hand.</p><h2 id="what-graphscribe-does" tabindex="-1">What GraphScribe does <a class="header-anchor" href="#what-graphscribe-does" aria-label="Permalink to “What GraphScribe does”">​</a></h2><p>GraphScribe exports Blueprints, Widget Blueprints, and DataAssets into formats you can put anywhere:</p><table tabindex="0"><thead><tr><th>Format</th><th>What it is</th><th>Good for</th></tr></thead><tbody><tr><td><strong>Markdown</strong></td><td>Clean, human-readable text</td><td>AI agents, code review, documentation, pull requests</td></tr><tr><td><strong>Graphify</strong></td><td>A knowledge graph with cross-project links</td><td>AI agents, knowledge bases, graph tools</td></tr><tr><td><strong>Mermaid</strong></td><td>Flowchart diagrams</td><td>Visualizing graphs and widget trees</td></tr><tr><td><strong>JSON</strong></td><td>A full structured dump of the graph</td><td>Custom tools and scripts</td></tr></tbody></table><p>It takes seconds to use: open a Blueprint, click <strong>GraphScribe</strong> in the toolbar, and an export dialog opens with a live preview. Pick a format, click <strong>Copy</strong> or <strong>Save As...</strong>, done.</p><h2 id="main-use-cases" tabindex="-1">Main use cases <a class="header-anchor" href="#main-use-cases" aria-label="Permalink to “Main use cases”">​</a></h2><ul><li><strong>Understand any Blueprint project with AI.</strong> Bought a Blueprint-only marketplace asset? Taking over a project with no documentation? New to Unreal and trying to figure out how a game actually works? Export the asset or the whole project to Markdown and Graphify, paste the exports into your favorite AI assistant, and ask about any node, design choice, event flow, or default value. Because the AI reads the actual exported logic, its answers match what&#39;s really inside the Blueprints.</li><li><strong>Document without writing docs.</strong> Export a feature&#39;s folder once and you have up-to-date, readable documentation for every Blueprint in it like variables, functions, graphs, and widget trees included.</li><li><strong>Review Blueprint changes like code.</strong> Commit exports next to your content, and &quot;changed a binary file&quot; becomes a diff anyone can read in a pull request.</li><li><strong>Map your project&#39;s architecture.</strong> Graphify&#39;s project-wide graph shows how your Blueprints connect which functions call which, which assets reference which classes in one file.</li></ul><h2 id="who-it-s-for" tabindex="-1">Who it&#39;s for <a class="header-anchor" href="#who-it-s-for" aria-label="Permalink to “Who it&#39;s for”">​</a></h2><ul><li><strong>New Unreal developers</strong> who want to understand existing Blueprints faster.</li><li><strong>Teams taking over or auditing projects</strong> with little or no documentation.</li><li><strong>Anyone feeding game logic to AI assistants</strong> and tired of pasting screenshots or describing graphs by hand.</li><li><strong>Technical artists and tools developers</strong> who need structured Blueprint data (JSON) for custom pipelines.</li></ul><p>No config, no scripting, no build step, just open the editor and export.</p><h2 id="why-it-matters-for-ai" tabindex="-1">Why it matters for AI <a class="header-anchor" href="#why-it-matters-for-ai" aria-label="Permalink to “Why it matters for AI”">​</a></h2><p>Plain Markdown shows you <em>one</em> Blueprint. But gameplay logic lives in <strong>many</strong> Blueprints that call each other. Graphify goes one step further: it builds a <strong>project-wide graph</strong> with stable links between Blueprints (<code>bp:</code>), functions (<code>fn:</code>), and classes (<code>cls:</code>), so AI can trace calls <em>across</em> your project and answer questions like:</p><ul><li>&quot;Who calls this GameInstance function?&quot;</li><li>&quot;Which Blueprint references this Ability?&quot;</li><li>&quot;What happens when the player picks up a coin?&quot;</li></ul><p>That cross-project linkage is impossible to get from <code>.uasset</code> binaries or from a pile of separate Markdown files. See <a href="/GraphScribe-Docs/guide/graphify-output.html">Graphify: AI-Ready Graphs</a> for the details.</p><h2 id="what-it-is-not" tabindex="-1">What it is NOT <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to “What it is NOT”">​</a></h2><p>GraphScribe does <strong>not</strong> replace the Blueprint editor. It doesn&#39;t give you an interactive &quot;find usages&quot; window. It is an <strong>export bridge</strong>: it takes what&#39;s in the editor and makes it readable and searchable everywhere else.</p>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};